// Ollama returns the model output as a JSON string in `response`.
// Never throw here: a malformed reply must still reach a human.
let intent = 'Unknown', draft = '';
try {
  const parsed = JSON.parse($json.response || '{}');
  intent = parsed.intent || 'Unknown';
  draft  = parsed.draft_reply || '';
} catch (e) {
  intent = 'Unknown';
  draft  = String($json.response || '').slice(0, 2000);
}

const hook = $('Smartlead Reply Webhook').first().json.body || {};

return {
  json: {
    intent,
    draft_reply: draft,
    is_positive: /positive|question/i.test(intent),
    lead_email: hook.email || hook.lead_email || hook.to_email || null,
    campaign_id: hook.campaign_id || null,
    reply_text: hook.msg || hook.reply || null,
  },
};

