// The resume callback shape varies by how the HUD calls back
// (query string, JSON body, or a bare ping). Default to REJECT: an
// ambiguous callback must never enroll a lead the gate already doubted.
const q = $json.query || {};
const b = $json.body || {};
const raw = String(q.decision ?? b.decision ?? q.action ?? b.action ?? '').toLowerCase();

const approved = raw === 'approve' || raw === 'approved' || raw === 'yes' || b.approved === true;

return {
  json: {
    approved,
    decision: raw || 'none',
    decided_by: b.user || q.user || 'orion-hud',
    raw_callback: { query: q, body: b },
  },
};

// Builds the {action, payload} contract the SalesGod Adapter expects.
// Reached from BOTH the auto-send branch and the human-approved branch;
// which one is inferred rather than duplicated into two nodes.
const lead = $('Catch Inbound Lead').first().json.body || {};

// Reuse the score the gate already produced. Re-running the 3B model here
// would double inference cost and could contradict the routing decision.
let gate = {};
try { gate = JSON.parse($('Hermes Intent & Confidence').first().json.response || '{}'); } catch (e) {}

let viaHuman = false;
try { viaHuman = $('Wait for Human').isExecuted; } catch (e) { viaHuman = false; }

let approval = null;
if (viaHuman) {
  try { approval = $('Parse Approval Decision').first().json; } catch (e) {}
}

// Hunter is email-only, so phone is expected to be null. Rather than bolt on a
// third-party lookup, hand SalesGod every identifier it can resolve a number
// from and let it enrich natively on receipt.
const phone = lead.phone || null;

const firmographics = {
  company_name:   lead.company || null,
  company_domain: lead.companyDomain || null,
  job_title:      lead.title || null,
  linkedin_url:   lead.linkedinUrl || null,
};

// Which vectors are actually populated, so a null phone is diagnosable rather
// than a silent enrichment failure on their side.
const vectors = Object.entries(firmographics)
  .filter(([, v]) => v)
  .map(([k]) => k);

return {
  json: {
    action: 'inbound_routing',
    payload: {
      email:      lead.email,
      first_name: lead.firstName,
      last_name:  lead.lastName,
      phone,

      ...firmographics,

      enrichment: {
        needs_phone_lookup: phone === null,
        available_vectors:  vectors,
        vector_count:       vectors.length,
      },

      qualification: {
        intent:     gate.intent ?? null,
        confidence: gate.confidence ?? null,
        route:      viaHuman ? 'human_approved' : 'auto_qualified',
        decided_by: viaHuman ? (approval?.decided_by ?? 'orion-hud') : 'llama3.2:3b',
      },

      smartlead: {
        campaign_id: '3744225',
        enrolled:    true,
        response_id: $json.id ?? $json.data?.id ?? null,
      },

      source: lead.source || 'lead-generation-pipeline',
      dedupe_key: `salesgod:inbound:${lead.email}`,
    },
  },
};
